function main(req) {
  const body = jsonParse(req.body, {});
  const width = Math.min(Math.max(parseInt(body.width) || 300, 10), 2000);
  const height = Math.min(Math.max(parseInt(body.height) || 200, 10), 2000);
  const bg = (body.bg || '4a90d9').replace(/[^a-fA-F0-9]/g, '').substring(0, 6);
  const fg = (body.fg || 'ffffff').replace(/[^a-fA-F0-9]/g, '').substring(0, 6);
  const text = (body.text || `${width}×${height}`).substring(0, 50);
  const fontSize = Math.max(12, Math.min(width, height) / 8);

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
  <rect width="100%" height="100%" fill="#${bg}"/>
  <text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle"
        font-family="Arial,sans-serif" font-size="${fontSize}" fill="#${fg}">
    ${text}
  </text>
</svg>`;

  return {
    status: 200,
    headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' },
    body: svg
  };
}
